@Transactional
public Long order(Long memberId, Long itemId, int count) {
    Order order = Order.create(memberId, itemId, count);
    orderRepository.save(order);

    // 같은 트랜잭션 안에서 DB 에 저장한다 (카프카를 안 부른다)
    outboxRepository.save(new OutboxEvent(
        UUID.randomUUID().toString(),      // eventId (7.5절의 멱등 키)
        "order.placed.v1",                 // topic
        order.getId().toString(),          // key
        toJson(new OrderPlaced(order))     // payload
    ));

    return order.getId();
}

// 별도 스레드/프로세스
@Scheduled(fixedDelay = 200)
public void publish() {
    var batch = outboxRepository.findUnpublished(100);
    for (var e : batch) {
        kafkaTemplate.send(e.topic(), e.key(), e.payload())
            .whenComplete((r, ex) -> {
                if (ex == null) outboxRepository.markPublished(e.id());
            });
    }
}
